export function useItem(id){const item=items[id];if(!item?.effect||!owned(id))return 'You do not have that usable item.';if(item.effect.type==='combat-tool'){const c=state.combat;if(!c)return 'That item is useful during combat.';const monster=monsterForId(c.monsterId);if(!item.effect.targetTags.some(tag=>monster.tags?.includes(tag)))return `${item.name} has no special effect on ${monster.name}; it is not consumed.`;removeItem(id,1);const damage=Math.max(1,item.effect.damage-Math.floor(c.defense/2));c.hp-=damage;c.physicalResistanceReductionTurns=Math.max(c.physicalResistanceReductionTurns||0,item.effect.resistanceReductionTurns||0)+1;bumpCareer('damageDealt',damage);let text=`${item.name} deals ${damage} damage and thins the gas cloud; its physical resistance is reduced for your next hit.`;if(c.hp<=0){const defeated={...c};state.combat=null;const encounter=state.dungeon.encounters.at(-1);if(encounter)encounter.cleared=true;text+=` ${c.displayName} disperses.`+lootReward(monster,defeated);tickTemporaryEffects();persist();return text}text+=enemyTurn()+tickBurn();tickCombatEffects();persist();return text}if(item.effect.type==='heal'){state.player.hp=Math.min(state.player.maxHp,state.player.hp+item.effect.amount);removeItem(id,1);const enemy=state.combat?enemyTurn():'';const burn=tickBurn();tickCombatEffects();persist();return `You use ${item.name}.${enemy}${burn}`}if(item.effect.type==='buff'){removeItem(id,1);addTemporaryEffect(item.effect.name,item.effect.value,item.effect.encounters);const enemy=state.combat?enemyTurn():'';const burn=tickBurn();tickCombatEffects();persist();return `You use ${item.name}. ${item.effect.name} improves for ${item.effect.encounters} encounters.${enemy}${burn}`}return 'Nothing happens.'}
export function useTonic(){return useItem('healing-tonic')}
export function equipItem(id){const item=items[id];if(state.combat)return {ok:false,message:'You cannot change equipment during combat.'};if(!item?.slot||!owned(id))return {ok:false,message:'That item cannot be equipped.'};if(item.classes&&!item.classes.includes(state.player.class))return {ok:false,message:`${item.name} is limited to ${item.classes.join(' or ')}.`};state.equipment[item.slot]=id;recalculateStats();persist();return {ok:true,message:`Equipped ${item.name}.`}}
export function unequipSlot(slot){if(state.combat||!EQUIPMENT_SLOTS.includes(slot)||!state.equipment[slot])return false;delete state.equipment[slot];recalculateStats();persist();return true}
const coreShopStock=['healing-tonic','rusty-sword','leather-armor'];
