function currentShopIds(){state.town.shop=state.town.shop||{rotation:0,rotatingIds:[]};const shop=state.town.shop;if(!Array.isArray(shop.rotatingIds)||shop.rotatingIds.length!==3||shop.rotatingIds.some(id=>!shopStock.includes(id)||coreShopStock.includes(id))){shop.rotatingIds=rotateShopIds(shop.rotation||0);persist()}return [...coreShopStock,...shop.rotatingIds]}
