export function buyPrice(id,merchantId='juniper'){const item=items[id],profile=merchantProfiles[merchantId]||merchantProfiles.juniper,multiplier=profile?.buyMultiplier||1;return Math.max(1,Math.floor((item?.buyValue||0)*multiplier*(1-equippedEffect('buyDiscount'))))}
export function buyItem(id,priceOverride=null){const item=items[id];if(!item||!currentShopIds().includes(id))return {ok:false,message:'That item is not on Juniper’s shelf.'};if(item.classes&&!item.classes.includes(state.player.class))return {ok:false,message:`${item.name} is limited to ${item.classes.join(' or ')}.`};const price=priceOverride??buyPrice(id);if(state.town.gold<price)return {ok:false,message:'Not enough gold.'};if(!canAddItem(id,1))return {ok:false,message:'Your pack is full. Sell something or clear a slot first.'};state.town.gold-=price;bumpCareer('goldSpent',price);addItem(id,1,{sourceType:'purchase',sourceName:'Juniper Dunn',acquiredFloor:0});persist();return {ok:true,message:`Bought ${item.name} for ${price} gold.`}}
export function salePrice(id){const item=items[id];return Math.max(1,Math.floor((item?.sellValue||0)*(1+equippedEffect('sellBonus'))))}
