export function canTrade(trade){return trade.requires.every(req=>owned(req.item)>=req.quantity&&canRemoveItem(req.item,req.quantity))&&state.town.gold>=trade.gold&&trade.gives.every(g=>canAddItem(g.item,g.quantity))}
