export function triggerEvent(id){if(!dungeonEvents[id])return false;state.dungeon.currentEventId=id;state.dungeon.inDungeon=true;persist();return true}
export function triggerRandomEvent(){state.dungeon.inDungeon=true;const event=openRandomEvent(state.dungeon.floor,state.dungeon.x,state.dungeon.y);return event?.id||null}
export function revealLandmark(id){const event=Object.values(dungeonEvents).find(e=>e.choices.some(c=>c.outcomes?.some(o=>o.type==='discover'&&o.landmark===id)));if(!event)return false;state.dungeon.inDungeon=true;state.dungeon.currentEventId=event.id;return resolveDungeonEvent(event.id,event.choices.find(c=>c.outcomes?.some(o=>o.type==='discover'&&o.landmark===id)).id).ok}
export function qaSetTemporaryEffect(name,value=1,encounters=2){if(value===0){delete state.player.temporaryEffects?.[name];persist();return true}addTemporaryEffect(name,value,encounters);return true}
export function qaResetEventState(){state.dungeon.currentEventId=null;state.dungeon.eventState={};state.dungeon.eventFlags={};state.dungeon.eventHistory=[];state.dungeon.eventedCells=[];state.dungeon.rooms={};state.dungeon.landmarks=[];persist()}
export function qaSetRoom(roomId){if(!roomTypes[roomId])return false;state.dungeon.inDungeon=true;state.dungeon.rooms[cellKey(state.dungeon.floor,state.dungeon.x,state.dungeon.y)]=roomId;persist();return true}
export function talkNpc(id){const npc=dungeonNpcs[id];if(!npc)return 'The visitor gives an unhelpful nod.';if(id==='kobold-trader')townFlag('pipKnown');if(id==='lost-surveyor')townFlag('nellKnown');const visits=state.town.npcProgress?.[id]||0;if(id==='kobold-trader'){if(state.dungeon.floor>=3)return visits?`Pip flips to a new page. “The deeper floor has better merchandise and worse liability.”`:'“Floor three prices are final. I have checked with myself.”';if(visits)return 'Pip recognizes you and updates the ledger. The prices remain emotionally flexible.'}if(id==='lost-surveyor'){if(state.dungeon.floor>=2){state.dungeon.eventFlags['met-nell-deeper']=true;persist();return visits?'Nell has marked the impossible geometry as “expected variance.”':'Nell is relieved to see another person. She gives you her deeper-floor survey note.'}if(visits)return 'Nell has walked in a circle and insists it was a planned calibration.'}return npc.line}
export function storeStock(){return currentShopIds().map(id=>items[id])}
export function xpToNext(){return state.player.level*25-state.player.xp}

// Development-only actions are also kept out of the regular game action paths.
export function qaGiveItem(id,qty=1){return addItem(id,qty)}
export function qaRemoveItem(id,qty=1){return removeItem(id,qty)}
export function qaGiveGold(amount){state.town.gold=Math.max(0,state.town.gold+amount);persist()}
export function qaSpawnMonster(id,floor=state.dungeon.floor,variantId=null,encounterLevel=null){const key=monsters[id]?id:Object.keys(monsters).find(monsterId=>monsters[monsterId].id===id);if(!key)return false;state.dungeon.inDungeon=true;state.combat=null;beginCombat(key,state.dungeon.x,state.dungeon.y,{floor:Number(floor)||1,variantId,encounterLevel:Number.isFinite(Number(encounterLevel))?Number(encounterLevel):null});persist();return true}
export function qaEnemyScalingMatrix(){return ['rat','pocketSlime','kungFuGoose','fireWorm','paperMimic'].flatMap(id=>[1,3,5,10].filter(floor=>floor>=monsters[id].minDepth).map(floor=>{const instance=scaleEnemy(monsters[id],floor,null),threat=state.player?threatAssessment(instance,{...state.player,fireResistance:equippedEffect('fireResistance')}):null;return {monster:monsters[id].name,floor,tier:monsters[id].baseTier,level:instance.encounterLevel,baseHp:monsters[id].hp,scaledHp:instance.maxHp,baseDefense:monsters[id].defense,scaledDefense:instance.defense,baseAttackRanges:monsters[id].attacks.map(a=>`${a.name} ${a.minDamage}-${a.maxDamage}`),scaledAttackRanges:instance.attacks.map(a=>`${a.name} ${a.minDamage}-${a.maxDamage} (w ${a.weight.toFixed(2)})`),baseXp:monsters[id].xp,scaledXp:instance.xp,goldMultiplier:Number(instance.goldMultiplier.toFixed(2)),threat:threat?.label,score:threat?.score}}))}
export function qaSpawnNpc(id){if(!dungeonNpcs[id])return false;state.dungeon.inDungeon=true;state.dungeon.currentNpcId=id;let visitor=state.dungeon.npcs.find(n=>n.id===id&&n.floor===state.dungeon.floor);if(visitor){visitor.x=state.dungeon.x;visitor.y=state.dungeon.y;visitor.resolved=false}else state.dungeon.npcs.push({id,floor:state.dungeon.floor,x:state.dungeon.x,y:state.dungeon.y,resolved:false});persist();return true}
