export function qaTeleportEdge(edge){const d=state.dungeon,map=d.map,candidates=edge==='north'?openCells(map).filter(([x,y])=>y===1):edge==='south'?openCells(map).filter(([x,y])=>y===map.height-2):edge==='west'?openCells(map).filter(([x,y])=>x===1):openCells(map).filter(([x,y])=>x===map.width-2);const cell=candidates[0];return cell?qaTeleport(cell[0],cell[1]):false}
