export function qaTeleport(x,y){const d=state.dungeon;x=Math.max(1,Math.min(d.map.width-2,Number(x)||1));y=Math.max(1,Math.min(d.map.height-2,Number(y)||1));if(wallAt(d,x,y))return false;d.inDungeon=true;d.currentEventId=null;d.currentNpcId=null;state.combat=null;d.x=x;d.y=y;reveal();persist();return true}
export function qaForceAttack(id){if(!state.combat)return false;if(!state.combat.attacks?.some(a=>a.id===id))return false;state.combat.forcedAttackId=id;persist();return true}
export function qaAttackPoolReport(monsterId,levels=[1,3,5,8,12],runs=1000){const monster=monsterForId(monsterId)||monsters[monsterId];if(!monster)return {error:`Unknown monster: ${monsterId}`};runs=Math.max(1,Math.min(5000,Math.floor(runs)));let seed=0x51f15e;const randomFn=()=>{seed=(Math.imul(seed,1664525)+1013904223)>>>0;return seed/4294967296};return levels.map(requestedLevel=>{const instance=scaleEnemy(monster,monster.minDepth,null,requestedLevel),counts=Object.fromEntries(instance.attacks.map(a=>[a.id,0]));for(let i=0;i<runs;i++){const chosen=chooseEnemyAttack(instance.aiProfile,instance.attacks,{hp:14,maxHp:24},randomFn);if(chosen)counts[chosen.id]++}return {requestedLevel,encounterLevel:instance.encounterLevel,aiProfile:instance.aiProfile,eligible:instance.attacks.map(a=>({id:a.id,name:a.name,weight:Number(a.weight.toFixed(3)),damage:[a.minDamage,a.maxDamage],effect:a.effect||null,effectChance:a.effectChance??null})),locked:(monster.attacks||[]).filter(a=>(a.unlockLevel||1)>instance.encounterLevel).map(a=>({id:a.id,name:a.name,unlockLevel:a.unlockLevel})),simulations:runs,selected:Object.fromEntries(Object.entries(counts).map(([id,count])=>[id,`${(100*count/runs).toFixed(1)}%`]))}})}
export function qaSetResources(gold,hp,mp){state.town.gold=Math.max(0,Number(gold)||0);state.player.hp=Math.max(1,Math.min(state.player.maxHp,Number(hp)||1));state.player.mp=Math.max(0,Math.min(state.player.maxMp,Number(mp)||0));persist()}
export function qaSetClass(cls){if(!STARTING_CLASSES[cls]||!state.player)return false;const base=STARTING_CLASSES[cls],hpRatio=state.player.hp/state.player.maxHp,mpRatio=state.player.maxMp?state.player.mp/state.player.maxMp:1;state.player.class=cls;state.player.baseStr=base.str;state.player.baseAgi=base.agi;state.player.baseMind=base.mind;state.player.baseVit=base.vit;state.player.baseMaxHp=base.hp+(state.player.level-1)*2;state.player.baseMaxMp=base.mp+(state.player.level-1);recalculateStats();state.player.hp=Math.round(state.player.maxHp*hpRatio);state.player.mp=Math.round(state.player.maxMp*mpRatio);persist();return true}
export function qaSetLevel(level){const p=state.player;if(!p)return false;const n=Math.max(1,Math.min(30,Math.floor(Number(level)||1))),base=STARTING_CLASSES[p.class];p.level=n;p.xp=0;p.baseMaxHp=base.hp+(n-1)*2;p.baseMaxMp=base.mp+(n-1);p.baseVit=base.vit+(n-1);recalculateStats();p.hp=p.maxHp;p.mp=p.maxMp;persist();return true}
export function qaStartQuest(id){if(!quests[id]||state.quests.completed.includes(id)||state.quests.active.some(q=>q.id===id))return false;state.quests.available=state.quests.available.filter(q=>q!==id);state.quests.available.push(id);return acceptQuest(id)}
export function qaResetCareer(){state.career={deepestFloor:state.dungeon.deepestFloor||1};state.achievements={unlocked:{}};persist()}
export function qaUnlockAchievement(id){return unlockAchievement(id)}
export function qaEconomySimulation(runs=100,floor=1){runs=Math.max(1,Math.min(1000,Math.floor(runs)));floor=Math.max(1,Math.floor(floor));const rows=(floorEncounterTable[floor]||floorEncounterTable[3]).filter(row=>monsters[row.id]&&monsters[row.id].minDepth<=floor),total=rows.reduce((n,r)=>n+r.weight,0);let gold=0,xp=0,incoming=0;const rarityCounts={common:0,uncommon:0,rare:0,strange:0};let seed=123456789;const rand=()=>{seed=(Math.imul(seed,1664525)+1013904223)>>>0;return seed/4294967296},weighted=(list,key)=>{let n=rand()*list.reduce((sum,row)=>sum+row[key],0);for(const row of list){n-=row[key];if(n<0)return row}return list.at(-1)};for(let i=0;i<runs;i++){const row=weighted(rows,'weight'),m=monsters[row.id];let variant=null,variantRoll=rand();for(const candidate of enemyVariants){variantRoll-=candidate.spawnChance;if(variantRoll<0){variant=candidate;break}}const instance=scaleEnemy(m,floor,variant),[lo,hi]=m.gold;gold+=Math.floor((lo+rand()*(hi-lo+1))*instance.rewardMultipliers.gold);xp+=instance.xp;const attack=weighted(instance.attacks,'weight');if(rand()<(attack.accuracy??.95))incoming+=Math.max(1,Math.floor(rand()*(attack.maxDamage-attack.minDamage+1))+attack.minDamage-2);const table=lootTables[m.lootTable]||[];if(table.length){const adjusted=table.map(item=>{const rarity=items[item.item]?.rarity||'common',factor=(rarities[rarity]?.weight||62)/62,mult=rarity==='rare'||rarity==='strange'?instance.lootMultiplier||1:1;return {...item,rarity,weight:item.weight*factor*mult}});rarityCounts[weighted(adjusted,'weight').rarity]++}}return {runs,floor,assumedPlayerDefense:2,averageGold:Number((gold/runs).toFixed(2)),averageXp:Number((xp/runs).toFixed(2)),averageIncomingDamagePerEnemyAction:Number((incoming/runs).toFixed(2)),averageLootRarity:Object.fromEntries(Object.entries(rarityCounts).map(([key,value])=>[key,`${(100*value/runs).toFixed(1)}%`]))}}
export function qaRevealNearby(){const d=state.dungeon;for(const [dx,dy] of [[0,0],[0,-1],[1,0],[0,1],[-1,0]]){const x=d.x+dx,y=d.y+dy;if(!wallAt(d,x,y)){const k=`${d.floor}:${x},${y}`;if(!d.explored.includes(k))d.explored.push(k)}}persist()}
export function qaRevealReturnRoute(){const d=state.dungeon,target={x:d.map.upStairs[0],y:d.map.upStairs[1]},key=p=>`${p.x},${p.y}`,queue=[{x:d.x,y:d.y}],prev=new Map([[key(queue[0]),null]]);while(queue.length){const p=queue.shift();if(key(p)===key(target))break;for(const [dx,dy] of [[0,-1],[1,0],[0,1],[-1,0]]){const next={x:p.x+dx,y:p.y+dy},k=key(next);if(!wallAt(d,next.x,next.y)&&!prev.has(k)){prev.set(k,key(p));queue.push(next)}}}if(!prev.has(key(target)))return false;let at=key(target);while(at){const [x,y]=at.split(',').map(Number),cell=`${d.floor}:${x},${y}`;if(!d.explored.includes(cell))d.explored.push(cell);at=prev.get(at)}persist();return true}
export function qaSetStat(name,value){if(!['baseStr','baseAgi','baseMind','baseVit','baseMaxHp','baseMaxMp'].includes(name))return false;state.player[name]=Math.max(0,Math.min(99,Number(value)||0));recalculateStats();persist();return true}
export function qaClearInventory(){state.inventory=[];state.equipment={};recalculateStats();persist()}
